// Monta a planilha estilizada (Painel + Transações) na cor do banco.
const cfg = $('Configurações').first().json;

// ---------- Cores ----------
const PALETA = {
  nubank: '#820AD1', itau: '#EC7000', inter: '#FF7A00', bradesco: '#CC092F',
  santander: '#EC0000', bancodobrasil: '#465EFF', bb: '#465EFF', caixa: '#005CA9',
  c6: '#242424', c6bank: '#242424', picpay: '#21C25E', mercadopago: '#009EE3',
  sicredi: '#3FA110', sicoob: '#003641', btg: '#0D2B4E', btgpactual: '#0D2B4E',
  pagbank: '#00A868', neon: '#0080FF', next: '#00C853', original: '#00A651'
};
const chave = String(cfg.banco || '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().replace(/[^a-z0-9]/g, '');
let hex = String(cfg.corPersonalizada || '').trim() || PALETA[chave] || '#4F46E5';
if (!hex.startsWith('#')) hex = '#' + hex;
if (!/^#[0-9a-fA-F]{6}$/.test(hex)) hex = '#4F46E5';

const n = parseInt(hex.slice(1), 16);
const r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
const cor = (rr, gg, bb) => ({ red: rr / 255, green: gg / 255, blue: bb / 255 });
const tom = f => cor(r + (255 - r) * f, g + (255 - g) * f, b + (255 - b) * f);

const PRINCIPAL = cor(r, g, b);
const CLARO = tom(0.93);
const MEDIO = tom(0.75);
const lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
const TEXTO_SOBRE = lum > 0.65 ? cor(17, 24, 39) : cor(255, 255, 255);
const SUBTEXTO_SOBRE = lum > 0.65 ? cor(55, 65, 81) : tom(0.7);
const BRANCO = cor(255, 255, 255);
const CINZA = cor(107, 114, 128);
const VERDE = cor(22, 163, 74);
const VERMELHO = cor(220, 38, 38);
const VERMELHO_SUAVE = cor(248, 113, 113);
const FONTE = 'Inter';

const PAINEL = 0, TX = 1, LINHAS = 5000;
const T = "'Transações'!";
const nomeBanco = String(cfg.banco || 'Meu banco');

// ---------- Helpers ----------
const rg = (sheetId, r1, r2, c1, c2) => ({
  sheetId, startRowIndex: r1, endRowIndex: r2, startColumnIndex: c1, endColumnIndex: c2
});
const formato = (range, f, campos) => ({
  repeatCell: { range, cell: { userEnteredFormat: f }, fields: 'userEnteredFormat(' + campos + ')' }
});
const valor = v => typeof v === 'number'
  ? { numberValue: v }
  : String(v).startsWith('=') ? { formulaValue: v } : { stringValue: String(v) };
const celulas = (sheetId, row, col, linhas) => ({
  updateCells: {
    start: { sheetId, rowIndex: row, columnIndex: col },
    rows: linhas.map(l => ({ values: l.map(v => v === null ? {} : { userEnteredValue: valor(v) }) })),
    fields: 'userEnteredValue'
  }
});
const mesclar = range => ({ mergeCells: { range, mergeType: 'MERGE_ALL' } });
const colunas = (sheetId, c1, c2, px) => ({
  updateDimensionProperties: {
    range: { sheetId, dimension: 'COLUMNS', startIndex: c1, endIndex: c2 },
    properties: { pixelSize: px }, fields: 'pixelSize'
  }
});
const linhas = (sheetId, r1, r2, px) => ({
  updateDimensionProperties: {
    range: { sheetId, dimension: 'ROWS', startIndex: r1, endIndex: r2 },
    properties: { pixelSize: px }, fields: 'pixelSize'
  }
});
const MOEDA = { type: 'CURRENCY', pattern: '"R$ "#,##0.00' };
const DATA = { type: 'DATE', pattern: 'dd/mm/yyyy' };

// Soma (em valor absoluto) das transações de um tipo entre duas datas
const soma = (tipo, ini, fim) =>
  `=SUMPRODUCT((${T}$F$2:$F="${tipo}")*(${T}$B$2:$B>=${ini})*(${T}$B$2:$B<=${fim})*ABS(${T}$D$2:$D))`;
const INI_MES = 'EOMONTH(TODAY(),-1)+1';
const FIM_MES = 'EOMONTH(TODAY(),0)';

// ---------- Corpo de criação ----------
const cabecalhos = ['id', 'data', 'descricao', 'valor', 'categoria', 'tipo', 'conta'];
const createBody = {
  properties: { title: cfg.nomePlanilha, locale: 'en_US', timeZone: 'America/Sao_Paulo' },
  sheets: [
    {
      properties: {
        sheetId: PAINEL, title: 'Painel', index: 0,
        gridProperties: { hideGridlines: true, rowCount: 60, columnCount: 20 },
        tabColorStyle: { rgbColor: PRINCIPAL }
      }
    },
    {
      properties: {
        sheetId: TX, title: 'Transações', index: 1,
        gridProperties: { frozenRowCount: 1, rowCount: LINHAS, columnCount: 7 },
        tabColorStyle: { rgbColor: MEDIO }
      },
      data: [{
        startRow: 0, startColumn: 0,
        rowData: [{ values: cabecalhos.map(h => ({ userEnteredValue: { stringValue: h } })) }]
      }]
    }
  ]
};

// ---------- Estilização ----------
const req = [];

// ===== Aba Transações =====
req.push(formato(rg(TX, 0, LINHAS, 0, 7), { textFormat: { fontFamily: FONTE, fontSize: 10 }, verticalAlignment: 'MIDDLE' }, 'textFormat,verticalAlignment'));
req.push(formato(rg(TX, 0, 1, 0, 7), {
  backgroundColor: PRINCIPAL,
  textFormat: { fontFamily: FONTE, fontSize: 10, bold: true, foregroundColor: TEXTO_SOBRE },
  verticalAlignment: 'MIDDLE', padding: { left: 8 }
}, 'backgroundColor,textFormat,verticalAlignment,padding'));
req.push(linhas(TX, 0, 1, 38));
req.push(linhas(TX, 1, LINHAS, 26));
req.push(colunas(TX, 0, 1, 80));
req.push(colunas(TX, 1, 2, 100));
req.push(colunas(TX, 2, 3, 340));
req.push(colunas(TX, 3, 4, 120));
req.push(colunas(TX, 4, 5, 170));
req.push(colunas(TX, 5, 6, 90));
req.push(colunas(TX, 6, 7, 200));
req.push(formato(rg(TX, 1, LINHAS, 0, 1), { textFormat: { fontFamily: FONTE, fontSize: 8, foregroundColor: CINZA } }, 'textFormat'));
req.push(formato(rg(TX, 1, LINHAS, 1, 2), { numberFormat: DATA, horizontalAlignment: 'CENTER' }, 'numberFormat,horizontalAlignment'));
req.push(formato(rg(TX, 1, LINHAS, 3, 4), { numberFormat: MOEDA }, 'numberFormat'));
req.push(formato(rg(TX, 1, LINHAS, 5, 6), { horizontalAlignment: 'CENTER' }, 'horizontalAlignment'));
req.push({
  addBanding: {
    bandedRange: {
      range: rg(TX, 0, LINHAS, 0, 7),
      rowProperties: { headerColorStyle: { rgbColor: PRINCIPAL }, firstBandColorStyle: { rgbColor: BRANCO }, secondBandColorStyle: { rgbColor: CLARO } }
    }
  }
});
for (const [tipo, c] of [['Entrada', VERDE], ['Saída', VERMELHO]]) {
  req.push({
    addConditionalFormatRule: {
      index: 0,
      rule: {
        ranges: [rg(TX, 1, LINHAS, 3, 4), rg(TX, 1, LINHAS, 5, 6)],
        booleanRule: {
          condition: { type: 'CUSTOM_FORMULA', values: [{ userEnteredValue: `=$F2="${tipo}"` }] },
          format: { textFormat: { bold: true, foregroundColorStyle: { rgbColor: c } } }
        }
      }
    }
  });
}
req.push({ setBasicFilter: { filter: { range: rg(TX, 0, LINHAS, 0, 7) } } });

// ===== Aba Painel =====
req.push(formato(rg(PAINEL, 0, 60, 0, 20), { textFormat: { fontFamily: FONTE, fontSize: 10 }, verticalAlignment: 'MIDDLE' }, 'textFormat,verticalAlignment'));
req.push(colunas(PAINEL, 0, 1, 24));
req.push(colunas(PAINEL, 1, 9, 125));
req.push(colunas(PAINEL, 9, 10, 24));
req.push(linhas(PAINEL, 0, 1, 16));
req.push(linhas(PAINEL, 1, 2, 64));
req.push(linhas(PAINEL, 2, 3, 30));
req.push(linhas(PAINEL, 3, 4, 18));
req.push(linhas(PAINEL, 4, 5, 30));
req.push(linhas(PAINEL, 5, 6, 52));
req.push(linhas(PAINEL, 6, 7, 22));
req.push(linhas(PAINEL, 7, 8, 32));

// Cabeçalho
req.push(mesclar(rg(PAINEL, 1, 2, 1, 9)));
req.push(mesclar(rg(PAINEL, 2, 3, 1, 9)));
req.push(celulas(PAINEL, 1, 1, [['💰  Minhas Finanças']]));
req.push(celulas(PAINEL, 2, 1, [[`${nomeBanco}  ·  atualizado automaticamente todo dia às 7h`]]));
req.push(formato(rg(PAINEL, 1, 2, 1, 9), {
  backgroundColor: PRINCIPAL, padding: { left: 16 },
  textFormat: { fontFamily: FONTE, fontSize: 22, bold: true, foregroundColor: TEXTO_SOBRE }
}, 'backgroundColor,padding,textFormat'));
req.push(formato(rg(PAINEL, 2, 3, 1, 9), {
  backgroundColor: PRINCIPAL, padding: { left: 16 }, verticalAlignment: 'TOP',
  textFormat: { fontFamily: FONTE, fontSize: 10, foregroundColor: SUBTEXTO_SOBRE }
}, 'backgroundColor,padding,verticalAlignment,textFormat'));

// Cartões de resumo
const cartoes = [
  { col: 1, titulo: 'ENTRADAS DO MÊS', formula: soma('Entrada', INI_MES, FIM_MES), cor: VERDE, moeda: true },
  { col: 3, titulo: 'SAÍDAS DO MÊS', formula: soma('Saída', INI_MES, FIM_MES), cor: VERMELHO, moeda: true },
  { col: 5, titulo: 'SALDO DO MÊS', formula: '=B6-D6', cor: PRINCIPAL, moeda: true },
  { col: 7, titulo: 'TRANSAÇÕES NO MÊS', formula: `=COUNTIFS(${T}$B$2:$B,">="&(${INI_MES}),${T}$B$2:$B,"<="&${FIM_MES})`, cor: PRINCIPAL, moeda: false }
];
for (const c of cartoes) {
  req.push(mesclar(rg(PAINEL, 4, 5, c.col, c.col + 2)));
  req.push(mesclar(rg(PAINEL, 5, 6, c.col, c.col + 2)));
  req.push(celulas(PAINEL, 4, c.col, [[c.titulo]]));
  req.push(celulas(PAINEL, 5, c.col, [[c.formula]]));
  req.push(formato(rg(PAINEL, 4, 5, c.col, c.col + 2), {
    backgroundColor: CLARO, padding: { left: 12 }, verticalAlignment: 'BOTTOM',
    textFormat: { fontFamily: FONTE, fontSize: 8, bold: true, foregroundColor: CINZA }
  }, 'backgroundColor,padding,verticalAlignment,textFormat'));
  const f = {
    backgroundColor: CLARO, padding: { left: 12 }, horizontalAlignment: 'LEFT',
    textFormat: { fontFamily: FONTE, fontSize: 20, bold: true, foregroundColor: c.cor }
  };
  if (c.moeda) f.numberFormat = MOEDA;
  req.push(formato(rg(PAINEL, 5, 6, c.col, c.col + 2), f,
    'backgroundColor,padding,horizontalAlignment,textFormat' + (c.moeda ? ',numberFormat' : '')));
  const borda = { style: 'SOLID_THICK', colorStyle: { rgbColor: BRANCO } };
  req.push({ updateBorders: { range: rg(PAINEL, 4, 6, c.col, c.col + 2), left: borda, right: borda } });
}
// Saldo verde/vermelho
for (const [tipo, c] of [['NUMBER_LESS', VERMELHO], ['NUMBER_GREATER_THAN_EQ', VERDE]]) {
  req.push({
    addConditionalFormatRule: {
      index: 0,
      rule: {
        ranges: [rg(PAINEL, 5, 6, 5, 7)],
        booleanRule: { condition: { type: tipo, values: [{ userEnteredValue: '0' }] }, format: { textFormat: { foregroundColorStyle: { rgbColor: c } } } }
      }
    }
  });
}

// Títulos das seções
const tituloSecao = (row, col, texto) => {
  req.push(celulas(PAINEL, row, col, [[texto]]));
  req.push(formato(rg(PAINEL, row, row + 1, col, col + 4), {
    textFormat: { fontFamily: FONTE, fontSize: 12, bold: true, foregroundColor: PRINCIPAL },
    borders: { bottom: { style: 'SOLID_MEDIUM', colorStyle: { rgbColor: MEDIO } } }
  }, 'textFormat,borders'));
};
tituloSecao(7, 1, 'Gastos por categoria · mês atual');
tituloSecao(7, 5, 'Entradas x Saídas · últimos 6 meses');
tituloSecao(24, 1, 'Maiores gastos do mês');

// Dados auxiliares dos gráficos (colunas K:P, ocultas)
req.push(celulas(PAINEL, 2, 10, [[
  `=IFERROR(ARRAYFORMULA(QUERY(FILTER({${T}E2:E,ABS(${T}D2:D)},${T}F2:F="Saída",${T}B2:B>=${INI_MES}),"select Col1, sum(Col2) where Col1 is not null group by Col1 order by sum(Col2) desc label Col1 'Categoria', sum(Col2) 'Total'",0)),{"Categoria","Total";"Sem gastos",0})`
]]));
const mensal = [['Mês', 'Entradas', 'Saídas']];
for (let i = 0; i < 6; i++) {
  const ini = `EOMONTH(TODAY(),${i - 6})+1`;
  const fim = `EOMONTH(TODAY(),${i - 5})`;
  mensal.push([`=TEXT(${ini},"mmm/yy")`, soma('Entrada', ini, fim), soma('Saída', ini, fim)]);
}
req.push(celulas(PAINEL, 2, 13, mensal));
req.push({
  updateDimensionProperties: {
    range: { sheetId: PAINEL, dimension: 'COLUMNS', startIndex: 10, endIndex: 16 },
    properties: { hiddenByUser: true }, fields: 'hiddenByUser'
  }
});

// Gráfico de rosca: gastos por categoria
req.push({
  addChart: {
    chart: {
      spec: {
        hiddenDimensionStrategy: 'SHOW_ALL',
        fontName: FONTE,
        backgroundColorStyle: { rgbColor: BRANCO },
        pieChart: {
          legendPosition: 'RIGHT_LEGEND',
          pieHole: 0.55,
          domain: { sourceRange: { sources: [rg(PAINEL, 3, 40, 10, 11)] } },
          series: { sourceRange: { sources: [rg(PAINEL, 3, 40, 11, 12)] } }
        }
      },
      position: { overlayPosition: { anchorCell: { sheetId: PAINEL, rowIndex: 8, columnIndex: 1 }, offsetYPixels: 6, widthPixels: 495, heightPixels: 300 } }
    }
  }
});

// Gráfico de colunas: entradas x saídas
req.push({
  addChart: {
    chart: {
      spec: {
        hiddenDimensionStrategy: 'SHOW_ALL',
        fontName: FONTE,
        backgroundColorStyle: { rgbColor: BRANCO },
        basicChart: {
          chartType: 'COLUMN',
          legendPosition: 'BOTTOM_LEGEND',
          headerCount: 1,
          axis: [{ position: 'BOTTOM_AXIS' }, { position: 'LEFT_AXIS' }],
          domains: [{ domain: { sourceRange: { sources: [rg(PAINEL, 2, 9, 13, 14)] } } }],
          series: [
            { series: { sourceRange: { sources: [rg(PAINEL, 2, 9, 14, 15)] } }, targetAxis: 'LEFT_AXIS', colorStyle: { rgbColor: PRINCIPAL } },
            { series: { sourceRange: { sources: [rg(PAINEL, 2, 9, 15, 16)] } }, targetAxis: 'LEFT_AXIS', colorStyle: { rgbColor: VERMELHO_SUAVE } }
          ]
        }
      },
      position: { overlayPosition: { anchorCell: { sheetId: PAINEL, rowIndex: 8, columnIndex: 5 }, offsetYPixels: 6, widthPixels: 495, heightPixels: 300 } }
    }
  }
});

// Top 5 maiores gastos do mês
req.push(linhas(PAINEL, 24, 25, 32));
req.push(linhas(PAINEL, 25, 31, 30));
req.push(celulas(PAINEL, 25, 1, [['Valor', 'Data', 'Categoria', 'Descrição']]));
req.push(formato(rg(PAINEL, 25, 26, 1, 9), {
  backgroundColor: PRINCIPAL, padding: { left: 10 },
  textFormat: { fontFamily: FONTE, fontSize: 9, bold: true, foregroundColor: TEXTO_SOBRE }
}, 'backgroundColor,padding,textFormat'));
req.push(celulas(PAINEL, 26, 1, [[
  `=IFERROR(ARRAYFORMULA(QUERY(FILTER({${T}B2:B,${T}C2:C,${T}E2:E,ABS(${T}D2:D)},${T}F2:F="Saída",${T}B2:B>=${INI_MES}),"select Col4, Col1, Col3, Col2 order by Col4 desc limit 5",0)),"Nenhum gasto registrado neste mês ainda")`
]]));
req.push(formato(rg(PAINEL, 26, 31, 1, 9), {
  padding: { left: 10 },
  borders: { bottom: { style: 'SOLID', colorStyle: { rgbColor: CLARO } } }
}, 'padding,borders'));
req.push(formato(rg(PAINEL, 26, 31, 1, 2), { numberFormat: MOEDA, textFormat: { fontFamily: FONTE, bold: true, foregroundColor: VERMELHO } }, 'numberFormat,textFormat'));
req.push(formato(rg(PAINEL, 26, 31, 2, 3), { numberFormat: DATA }, 'numberFormat'));
req.push(formato(rg(PAINEL, 26, 31, 3, 4), { textFormat: { fontFamily: FONTE, foregroundColor: CINZA } }, 'textFormat'));

// Por último, troca o idioma para pt-BR: as fórmulas já gravadas são convertidas pelo próprio Google
req.push({ updateSpreadsheetProperties: { properties: { locale: 'pt_BR' }, fields: 'locale' } });

return [{ json: { corUsada: hex, createBody, batchBody: { requests: req } } }];
